INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 1 المقدمة',
  '
ـ[حِصن المسلمِ مِن أذكار الكتاب والسُّنة]ـ
المؤلف: د. سعيد بن على بن وهف القحطاني
الناشر: مطبعة سفير، الرياض
توزيع: مؤسسة الجريسي للتوزيع والإعلان، الرياض
عدد الأجزاء: ١
[ترقيم الكتاب موافق للمطبوع]

بسم الله الرحمن الرحيم
[المقدمة]
إِنَّ الحَمْدَ للَّهِ، نَحْمَدُهُ، وَنَسْتَعِينُهُ، وَنَسْتَغْفِرُهُ، وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا، وَسَيِّئَاتِ أَعْمَالِنَا، مَنْ يَهْدِهِ اللَّهُ فَلاَ مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلاَ هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسُولُهُ، صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَأَصْحَابِهَ، وَمَنْ تَبِعَهُمْ بِإِحْسَانٍ إِلَى يَوْمِ الدِّينِ، وَسَلَّمَ تَسْلِيمَاً كَثِيرَاً، أَمَّا بَعْدُ:

فَهَذَا مُخْتَصَرٌ اخْتَصَرْتُهُ مِنْ كِتَابِي: ((الذِّكْرُ وَالدُّعَاءُ وَالعِلاَجُ بِالرُّقَى مِنَ الْكِتَابِ وَالسُّنَّةِ)) (١) اخْتَصَرْتُ فِيهِ قِسْمَ الأَذْكَارِ؛ لِيَكُونَ خَفِيفَ الْحَمْلِ فِي الأَسْفَارِ.
وَقَدِ اقْتَصَرْتُ عَلَى مَتْنِ الذِّكْرِ، وَاكْتَفَيْتُ فِي تَخْرِيجِهِ بِذِكْرِ مَصْدَرٍ أَوْ مَصْدَرَيْنِ مِمَّا وُجِدَ فِي الأَصْلِ، وَمَنْ أَرَادَ مَعْرِفَةَ الصَّحَابِيِّ أَوْ زِيَادَةً فِي التَّخِرِيجِ فَعَلَيْهِ بِالرُّجُوعِ إِلَى الأَصْلِ.

--- الحواشي ---
(١) وقد طبع الأصل المذكور، وللَّه الحمد، مع تخريج أحاديثه تخريجاً موسعاً في أربعة مجلدات. حصن المسلم في المجلد الأول والثاني منها.

وَأَسْأَلُ اللَّهَ - عز وجل - بِأَسْمَائِهِ الْحُسْنَى، وَصِفَاتِهِ الْعُلاَ أَنْ يَجْعَلَهُ خَالِصَاً لِوَجْهِهِ الْكَرِيمِ، وَأَنْ يَنْفَعَنِي بِهِ فِي حَيَاتِي، وَبَعْدَ مَمَاتِي، وَأَنْ يَنْفَعَ بِهِ مَنْ قَرَأَهُ، أَوْ طَبَعَهُ، أَوْ كَانَ سَبَباً فِي نَشْرِهِ؛ إِنَّهُ سُبْحَانَهُ وَلِيُّ ذَلِكَ، وَالْقَادِرُ عَلَيْهِ. وَصَلَّى اللَّهُ وَسَلَّمَ عَلَى نَبِيِّنَا مُحَمَّدٍ، وَعَلَى آلِهِ وَأَصْحَابِهِ، وَمَنْ تَبِعَهُمْ بِإِحْسَانٍ إِلَى يَوْمِ الدِّيْنِ.
المؤلف
حرر في شهر صفر ١٤٠٩هـ
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 2 فضل الذكر',
  '
فَضْلُ الذِّكِر
قَالَ اللَّهُ تَعَالَى: {فَاذْكُرُونِي أَذْكُرْكُمْ وَاشْكُرُواْ لِي وَلاَ تَكْفُرُونِ} (١)،
{يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْراً كَثِيراً} (٢)، {وَالذَّاكِرِينَ اللَّهَ كَثِيراً وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُم مَّغْفِرَةً وَأَجْراً عَظِيماً} (٣)، {وَاذْكُرْ رَّبَّكَ فِي نَفْسِكَ تَضَرُّعاً وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالآصَالِ وَلاَ تَكُن مِّنَ الْغَافِلِينَ} (٤)،

--- الحواشي ---
(١) سورة البقرة، الآية: ١٥٢.
(٢) سورة الأحزاب، الآية: ٤١.
(٣) سورة الأحزاب، الآية: ٣٥.
(٤) سورة الأعراف، الآية: ٢٠٥.

وَقَالَ النَّبِيُّ - صلى الله عليه وسلم -: ((مَثَلُ الَّذِي يَذْكُرُ رَبَّهُ، وَالَّذِي لاَ يَذْكُرُ ربَّهُ، مَثَلُ الْحَيِّ وَالْمَيِّتِ)) (١)، وَقَالَ - صلى الله عليه وسلم -: ((أَلاَ أُنبِّئُكُم بِخَيْرِ أَعْمَالِكُمْ، وَأَزْكَاهَا عِنْدَ مَلِيكِكُمْ، وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ، وَخَيْرٍ لَكُمْ مِنْ إِنْفَاقِ الذَّهَبِ وَالوَرِقِ، وَخَيْرٍ لَكُمْ مِنْ أَنْ تَلْقَوْا عَدُوَّكُمْ فَتَضْرِبُوا أَعْنَاقَهُمْ وَيَضْرِبُوا أَعْنَاقِكُم))؟ قَالُوا بَلَى.

--- الحواشي ---
(١) البخاري مع الفتح، ١١/ ٢٠٨، برقم ٦٤٠٧، ومسلم، ١/ ٥٣٩، برقم ٧٧٩، بلفظ: ((مثل البيت الذي يذكر اللَّه فيه والبيت الذي لا يذكر اللَّه فيه مثل الحي والميت))، ١/ ٥٣٩.

((ذِكْرُ اللَّهِ تَعَالَى)) (١)، وَقَالَ - صلى الله عليه وسلم -: ((يَقُولُ اللَّهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ، ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَأٍ، ذَكَرْتُهُ فِي مَلَأٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ شِبْراً، تَقَرَّبْتُ إِلَيْهِ ذِرَاعاً، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعاً، تَقَرَّبْتُ إِلَيْهِ بَاعاً، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً)) (٢)، وَعَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ - رضي الله عنه - أَنَّ رَجُلاً قَالَ:

--- الحواشي ---
(١) الترمذي، ٥/ ٤٥٩، برقم ٣٣٧٧، وابن ماجه، ٢/ ١٢٤، برقم ٣٧٩٠، وانظر: صحيح ابن ماجه، ٢/ ٣١٦، وصحيح الترمذي، ٣/ ١٣٩.
(٢) البخاري، ٨/ ١٧١، برقم ٧٤٠٥، ومسلم، ٤/ ٢٠٦١، برقم ٢٦٧٥، واللفظ للبخاري.

يَا رَسُولَ اللَّهِ، إِنَّ شَرَائِعَ الإِسْلاَمِ قَدْ كَثُرَتْ عَليَّ، فَأَخْبِرْنِي بِشَيْءٍ أَتَشَبَّثُ بِهِ. قَالَ: ((لاَ يَزَالُ لِسَانُكَ رَطْباً مِنْ ذِكْرِ اللَّهِ)) (١)، وَقَالَ - صلى الله عليه وسلم -: ((مَنْ قَرَأَ حَرْفاً مِنْ كِتَابِ اللَّهِ فَلَهُ بِهِ حَسَنَةٌ، وَالْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا، لاَ أَقُولُ: {الم} حَرْفٌ، وَلَكِنْ: أَلِفٌ حَرْفٌ، وَلاَمٌ حَرْفٌ، وَمِيْمٌ حَرْفٌ)) (٢). وَعَنْ عُقْبَةَ بْنِ عَامِرٍ - رضي الله عنه - قَالَ:

--- الحواشي ---
(١) الترمذي، ٥/ ٤٥٨، برقم ٣٣٧٥، وابن ماجه، ٢/ ١٢٤٦،٣٧٩٣، وصححه الألباني في: صحيح الترمذي، ٣/ ١٣٩، وصحيح ابن ماجه، ٢/ ٣١٧.
(٢) الترمذي، ٥/ ١٧٥، برقم ٢٩١٠، وصححه الألباني: صحيح الترمذي، ٣/ ٩، وصحيح الجامع الصغير، ٥/ ٣٤٠.

خَرَجَ رَسُولُ اللَّهِ - صلى الله عليه وسلم - وَنَحْنُ فِي الصُّفَّةِ، فَقَالَ: ((أَيُّكُمْ يُحِبُّ أَنْ يَغْدُوَ كُلَّ يَوْمٍ إِلَى بُطْحَانَ، أَوْ إِلَى الْعَقِيقِ، فَيَأْتيَ مِنْهُ بِنَاقَتَيْنِ كَوْمَاوَيْنِ فِي غَيْرِ إِثْمٍ وَلاَ قَطِيعَةِ رَحِمٍ))؟ فَقُلْنَا: يَا رَسُولَ اللَّهِ نُحِبُّ ذَلِكَ. قَالَ: ((أَفَلاَ يَغْدُو أَحَدُكُمْ إِلَى المَسْجِدِ فَيَعْلَمَ، أَوْ يَقْرَأَ آيَتَيْنِ مِنْ كِتَابِ اللَّهِ - عز وجل - خَيْرٌ لَهُ مِنْ نَاقَتَيْنِ، وَثَلاثٌ خَيْرٌ لَهُ مِنْ ثَلاَثٍ، وَأَرْبَعٌ خَيْرٌ لَهُ مِنْ أَرْبَعٍ، وَمِنْ أَعْدَادِهِنَّ مِنَ الإِبِلِ)) (١).

--- الحواشي ---
(١) مسلم، ١/ ٥٥٣، برقم ٨٠٣.

وَقَالَ - صلى الله عليه وسلم -: ((مَنْ قَعَدَ مَقْعَدَاً لَمْ يَذْكُرِ اللَّهَ فِيهِ، كَانَتْ عَلَيْهِ مِنَ اللَّهِ تِرَةٌ، وَمَنِ اضْطَجَعَ مَضْجِعاً لَمْ يَذْكُرِ اللَّهَ فِيهِ كَانَتْ عَلَيْهِ مِنَ اللَّهِ تِرَةٌ)) (١).
وقال - صلى الله عليه وسلم -: ((مَا جَلَسَ قَوْمٌ مَجْلِسَاً لَمْ يَذْكُرُوا اللَّهَ فِيهِ، وَلَمْ يُصَلُّوا عَلَى نَبِيِّهِمْ إِلاَّ كَانَ عَلَيْهِمْ تِرَةً، فَإِنْ شَاءَ عذَّبَهُمْ، وَإِنْ شَاءَ غَفَرَ لَهُمْ)) (٢).
وَقَالَ - صلى الله عليه وسلم -: ((مَا مِنْ قَوْمٍ يَقُومُونَ مِنْ

--- الحواشي ---
(١) أبو داود، ٤/ ٢٦٤، برقم ٤٨٥٦، وغيره، وانظر: صحيح الجامع، ٥/ ٣٤٢.
(٢) الترمذي، ٥/ ٤٦١، برقم ٣٣٨٠، وانظر: صحيح الترمذي، ٣/ ١٤٠.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 3 ١ - أذكار الاستيقاظ من النوم',
  '
مَجْلِسٍ لاَ يَذْكُرُونَ اللَّهَ فِيهِ إِلاَّ قَامُوا عَنْ مِثْلِ جِيفَةِ حِمَارٍ، وَكَانَ لهُمْ حَسْرةً)) (١).
١ - أَذْكَارُ الاسْتِيقَاظِ مِنَ النَّومِ
١ - (١) ((الْحَمْدُ للَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا، وَإِلَيْهِ النُّشُورُ)) (٢).
٢ - (٢) ((لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَريكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى

--- الحواشي ---
(١) أبو داود، ٤/ ٢٦٤، برقم ٤٨٥٥، وأحمد، ٢/ ٣٨٩، برقم ١٠٦٨٠، وانظر: صحيح الجامع، ٥/ ١٧٦.
(٢) البخاري مع الفتح، ١١/ ١١٣، برقم ٦٣١٤، ومسلم، ٤/ ٢٠٨٣، برقم ٢٧١١.

كُلِّ شَيْءٍ قَدِيرٌ، سُبْحَانَ اللَّهِ، وَالْحَمْدُ للَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَلِيِّ الْعَظِيمِ، رَبِّ اغْفرْ لِي)) (١).
٣ - (٣) ((الْحَمْدُ لِلَّهِ الَّذِي عَافَانِي فِي جَسَدِي، وَرَدَّ عَلَيَّ رُوحِي، وَأَذِنَ لي بِذِكْرِهِ)) (٢).
٤ - (٤) (({إِنَّ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ

--- الحواشي ---
(١) من قال ذلك غُفِرَ له، فإن دعا استجيب له، فإن قام فتوضأ ثم صلى قُبلت صلاته، البخاري مع الفتح، ٣/ ٣٩، برقم ١١٥٤، وغيره، واللفظ لابن ماجه، انظر: صحيح ابن ماجه، ٢/ ٣٣٥.
(٢) الترمذي، ٥/ ٤٧٣، برقم ٣٤٠١، وانظر: صحيح الترمذي، ٣/ ١٤٤.

وَاخْتِلاَفِ اللَّيْلِ وَالنَّهَارِ لَآيَاتٍ لأُوْلِي الألْبَابِ * الَّذِينَ يَذْكُرُونَ اللَّهَ قِيَاماً وَقُعُوداً وَعَلَىَ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِي خَلْقِ السَّمَوَاتِ وَالأَرْضِ رَبَّنَا مَا خَلَقْتَ هَذا بَاطِلاً سُبْحَانَكَ فَقِنَا عَذَابَ النَّارِ* رَبَّنَا إِنَّكَ مَن تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ وَمَا لِلظَّالِمِينَ مِنْ أَنصَارٍ* رَّبَّنَا إِنَّنَا سَمِعْنَا مُنَادِياً يُنَادِي لِلإِيمَانِ أَنْ آمِنُواْ بِرَبِّكُمْ فَآمَنَّا رَبَّنَا فَاغْفِرْ لَنَا ذُنُوبَنَا وَكَفِّرْ عَنَّا سَيِّئَاتِنَا وَتَوَفَّنَا مَعَ الأبْرَارِ* رَبَّنَا وَآتِنَا مَا وَعَدتَّنَا عَلَى رُسُلِكَ وَلاَ تُخْزِنَا يَوْمَ الْقِيَامَةِ إِنَّكَ لاَ تُخْلِفُ الْمِيعَادَ*

فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لاَ أُضِيعُ عَمَلَ عَامِلٍ مِّنكُم مِّن ذَكَرٍ أَوْ أُنثَى بَعْضُكُم مِّن بَعْضٍ فَالَّذِينَ هَاجَرُواْ وَأُخْرِجُواْ مِن دِيَارِهِمْ وَأُوذُواْ فِي سَبِيلِي وَقَاتَلُواْ وَقُتِلُواْ لأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الأَنْهَارُ ثَوَاباً مِّن عِندِ اللَّهِ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ * لاَ يَغُرَّنَّكَ تَقَلُّبُ الَّذِينَ كَفَرُواْ فِي الْبِلاَدِ * مَتَاعٌ قَلِيلٌ ثُمَّ مَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمِهَادُ * لَكِنِ الَّذِينَ اتَّقَوْاْ رَبَّهُمْ لَهُمْ جَنَّاتٌ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ خَالِدِينَ فِيهَا نُزُلاً مِّنْ عِندِ اللَّهِ وَمَا عِندَ
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
