(٢) أخرجه البخاري في الأدب المفرد، برقم ٦٩٥، ص٢٥٨ وصحح إسناده الألباني في صحيح الأدب المفرد، برقم ٥٣٦.
(٣) ذكره ابن حجر في فتح الباري، وعزاه إلى ابن أبي عاصم في كتاب الدعاء، انظر الفتح ١١/ ١١٨، وقال: فاجتمع من اختلاف الروايات خمس وعشرون خصلة.
(٤) لقول أنس بن مالك - رضي الله عنه -: ((من السنة إذ دخلت المسجد أن تَبدأ برجلك اليمنى، وإذا خرجت أن تبدأ برجلك اليسرى))، أخرجه الحاكم، ١/ ٢١٨، وصححه على شرط مسلم، ووافقه الذهبي، وأخرجه البيهقي، ٢/ ٤٤٢، وحسنه الألباني في سلسلة الأحاديث الصحيحة، ٥/ ٦٢٤، برقم ٢٤٧٨.
',
