(٦) انظر تخريج روايات الحديث السابق في دعاء دخول المسجد، رقم (٢٠) وزيادة: ((اللهم اعصمني من الشيطان الرجيم)) لابن ماجه. انظر: صحيح ابن ماجه، ١/ ١٢٩.
