INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 20 ٢٢ - التشهد',
  '
٢٢ - التَّشَهُّدُ
٥٢ - ((التَّحِيَّاتُ لِلَّهِ، وَالصَّلَواتُ، وَالطَّيِّباتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَشْهَدُ أَنَّ مُحَمَّداً عَبْدُهُ وَرَسولُهُ)) (١).
٢٣ - الصَّلاةُ عَلَى النَّبيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بَعْدَ التَّشَهُّدِ
٥٣ - (١) ((اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ، وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيتَ عَلَى إِبْرَاهِيمَ،

--- الحواشي ---
(١) البخاري مع الفتح، ٢/ ٣١١، برقم ٨٣١، ومسلم، ١/ ٣٠١، برقم ٤٠٢.
',
