INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 27 ٢٩ - الدعاء إذا تقلب ليلا',
  '
رَغْبَةً وَرَهْبَةً إِلَيْكَ، لاَ مَلْجَأَ وَلاَ مَنْجَا مِنْكَ إِلاَّ إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ)) (١).
٢٩ - الدُّعَاءُ إِذَا تَقَلَّبَ لَيْلاً
١١٢ - ((لاَ إِلَهَ إِلاَّ اللَّهُ الْوَاحِدُ الْقَهّارُ، رَبُّ السَّمَوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا الْعَزيزُ الْغَفَّارُ)) (٢).

--- الحواشي ---
(١) قال - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لمن قال ذلك: ((فإن مُتَّ مُتَّ على الفطرة)). البخاري مع الفتح، ١١/ ١١٣، برقم ٦٣١٣، ومسلم، ٤، ٢٠٨١، برقم ٢٧١٠.
(٢) يقول ذلك إذا تقلب من جنب إلى جنب في الليل. أخرجه الحاكم، وصححه ووافقه الذهبي، ١/ ٥٤٠، والنسائي في عمل اليوم والليلة، برقم ٢٠٢، وابن السني، برقم ٧٥٧، وانظر: صحيح الجامع ٤/ ٢١٣.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
