شَرِّهِمْ، جَلَّ ثَنَاؤُكَ وَعَزَّ جَارُكَ، وَتَبَارَكَ اسْمُكَ، وَلاَ إِلَهَ غَيْرُكَ)) (ثلاثَ مرَّاتٍ) (١).
٣٨ - الدُّعَاءُ عَلَى الْعَدُوِّ
١٣١ - ((اللَّهُمَّ مُنْزِلَ الْكِتَابِ، سَرِيعَ الْحِسَابِ، اهْزِمِ الأَحْزَابَ، اللَّهُمَّ اهزِمْهُمْ وَزَلْزِلْهُمْ)) (٢).
٣٩ - مَا يَقُولُ مَنْ خَافَ قَوْماً
١٣٢ - ((اللَّهُمَّ اكْفِنِيهِمْ بِمَا شِئْتَ)) (٣).

--- الحواشي ---
(١) البخاري في الأدب المفرد برقم ٧٠٨، وصححه الألباني في صحيح الأدب المفرد، برقم ٥٤٦.
(٢) مسلم، ٣/ ١٣٦٢، برقم ١٧٤٢.
(٣) مسلم، ٤/ ٢٣٠٠، برقم ٣٠٠٥.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 36 ٤٠ - دعاء من أصابه وسوسة في الإيمان',
  '
٤٠ - دُعَاءُ مَنْ أَصَابَهُ وَسْوَسَةٌ فِي الإِيمَانِ
١٣٣ - (١) ((يَسْتَعِيذُ بِاللَّهِ)) (١).
(٢) ((يَنْتَهِي عَمَّا وَسْوَسَ فِيهِ)) (٢).
١٣٤ - (٣) ((يَقُولُ: ((آمَنْتُ بِاللَّهِ وَرُسُلِهِ)) (٣).
١٣٥ - (٤) ((يَقْرَأُ قَوْلَهُ تَعَالَى: {هُوَ الْأوَّلُ وَالْآخِرُ وَالظّاهِرُ وَالْباطِنُ وَهُوَ بِكُلِّ شَيْءٍ عَلِيمٌ})) (٤).

--- الحواشي ---
(١) البخاري مع الفتح، ٦/ ٣٣٦، برقم ٣٢٧٦، ومسلم، ١/ ١٢٠،
برقم ١٣٤.
(٢) البخاري مع الفتح، ٦/ ٣٣٦، برقم ٣٢٧٦، ومسلم، ١/ ١٢٠،
برقم ١٣٤.
(٣) مسلم، ١/ ١١٩ - ١٢٠، برقم ١٣٤.
(٤) سورة الحديد، الآية: ٣. أبو داود، ٤/ ٣٢٩، برقم ٥١١٠، وحسنه الألباني في صحيح أبي داود، ٣/ ٩٦٢.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 37 ٤١ - دعاء قضاء الدين',
  '
٤١ - دُعَاءُ قَضَاءِ الدَّيْنِ
١٣٦ - (١) ((اللَّهُمَّ اكْفِنِي بِحَلاَلِكَ عَنْ حَرَامِكَ، وَأَغْنِنِي بِفَضْلِكِ عَمَّنْ سِوَاكَ)) (١).
١٣٧ - (٢) ((اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ، وَالْعَجْزِ وَالْكَسَلِ، وَالْبُخْلِ وَالْجُبْنِ، وَضَلَعِ الدَّيْنِ وَغَلَبَةِ الرِّجَالِ)) (٢).
٤٢ - دُعَاءُ الوَسْوَسَةِ فِي الصَّلاَةِ وَالْقِرَاءَةِ
١٣٨ - ((أَعُوذُ بِاللَّهِ مِنَ الشَّيطَانِ الرَّجِيمِ، وَاتْفُلْ عَلَى يَسَارِكَ -ثلاثاً-)) (٣).

--- الحواشي ---
(١) الترمذي، ٥/ ٥٦٠، برقم ٣٥٦٣، وانظر: صحيح الترمذي، ٣/ ١٨٠.
(٢) البخاري، ٧/ ١٥٨، برقم ٢٨٩٣، وتقدم ص ٨٣، برقم ١٢١.
(٣) مسلم، ٤/ ١٧٢٩، برقم ٢٢٠٣، من حديث عثمان بن أبي العاص - رضي الله عنه -، وفيه ففعلت ذلك، فأذهبه اللَّه عني.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 38 ٤٣ - دعاء من استصعب عليه أمر',
  '
٤٣ - دُعَاءُ مَنِ اسْتَصْعَبَ عَلَيْهِ أَمْرٌ
١٣٩ - ((اللَّهُمَّ لاَ سَهْلَ إِلاَّ مَا جَعَلْتَهُ سَهْلاً، وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلاً)) (١).
٤٤ - مَا يَقُولُ وَيَفْعَلُ مَنْ أَذْنَبَ ذَنْباً
١٤٠ - ((مَا مِنْ عَبْدٍ يُذنِبُ ذَنْباً فَيُحْسِنُ الطُّهُورَ، ثُمَّ يَقُومُ فَيُصَلِّي رَكْعَتَيْنِ، ثُمَّ يَسْتَغْفِرُ اللَّهَ إِلاَّ غَفَرَ اللَّهُ لَهُ)) (٢).

--- الحواشي ---
(١) رواه ابن حبان في صحيحه، برقم ٢٤٢٧ (موارد)، وابن السني، برقم ٣٥١، وقال الحافظ: ((هذا حديث صحيح))، وصححه عبد القادر الأرناؤوط في تخريج الأذكار للنووي، ص١٠٦.
(٢) أبو داود، ٢/ ٨٦، برقم ١٥٢١، والترمذي، ٢/ ٢٥٧، برقم ٤٠٦، وصححه الألباني في صحيح أبي داود، ١/ ٢٨٣.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 39 ٤٥ - دعاء طرد الشيطان ووساوسه',
  '
٤٥ - دُعَاءُ طَرْدِ الشَّيطَانِ وَوَسَاوِسِهِ
١٤١ - (١) ((الْاسْتِعَاذَةُ بِاللَّهِ مِنْهُ)) (١).
١٤٢ - (٢) ((الْأَذَانُ)) (٢).
١٤٣ - (٣) ((الْأَذْكَارُ وَقِرَاءَةُ الْقُرْآنِ)) (٣).

--- الحواشي ---
(١) أبو داود، ١/ ٢٠٣، برقم، وابن ماجه، ١/ ٢٦٥، برقم ٨٠٧، وتقدم تخريجه برقم ٣١، وانظر: سورة المؤمنون، الآيتان: ٩٧ - ٩٨.
(٢) مسلم، ١/ ٢٩١، برقم ٣٨٩، والبخاري، ١/ ١٥١، برقم ٦٠٨.
(٣) ((لا تجعلوا بيوتكم مقابر، إن الشيطان ينفر من البيت الذي تُقرأ فيه سورة البقرة))، رواه مسلم، ١/ ٥٣٩، برقم ٧٨٠، ومما يطرد الشيطان أذكار الصباح والمساء، والنوم والاستيقاظ، وأذكار دخول المنزل والخروج منه، وأذكار دخول المسجد والخروج منه، وغير ذلك من الأذكار المشروعة، مثل: قراءة آية الكرسي عند النوم، والآيتين الأخيرتين من سورة البقرة، ومن قال: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير مائة مرة، كانت له حرزاً من الشيطان يومه كله، وكذا الأذان
يطرد الشيطان.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 40 ٤٦ - الدعاء حينما يقع ما لا يرضاه أو غلب على أمره',
  '
٤٦ - الدُّعَاءُ حِينَمَا يَقَعُ مَا لاَ يَرْضَاهُ أَوْ غُلِبَ عَلَى أَمْرِهِ
١٤٤ - ((قَدَرُ اللَّهُ وَمَا شَاءَ فَعَلَ)) (١).
٤٧ - تَهْنِئَةُ المَوْلُودِ لَهُ وَجَوَابُهُ
١٤٥ - ((بَارَكَ اللَّهُ لَكَ فِي الْمَوْهُوبِ لَكَ، وَشَكَرْتَ الْوَاهِبَ، وَبَلَغَ أَشُدَّهُ، وَرُزِقْتَ بِرَّهُ)) (٢). وَيَرُدُّ عَلَيْهِ الْمُهَنَّأُ فَيَقُولُ: ((بَارَكَ اللَّهُ لَكَ وَبَارَكَ عَلَيْكَ، وَجَزَاكَ اللَّهُ خَيْراً، وَرَزَقَكَ اللَّهُ مِثْلَهُ، وَأَجْزَلَ ثَوَابَكَ)) (٣).

--- الحواشي ---
(١) ((المؤمن القوي خير وأحبّ إلى اللَّه من المؤمن الضعيف، وفي كلٍّ خير، احرص على ما ينفعك، واستعن باللَّهِ ولا تعجز، وإن أصابك شيء فلا تقل: لو أني فعلت كان كذا وكذا، ولكن قل قدَرُ اللَّه وما شاء فعل، فإنَّ لو تفتح عمل الشيطان)). مسلم، ٤/ ٢٠٥٢، برقم ٢٦٦٤.
(٢) ذُكِرَ من كلام الحسن البصري. انظر: تحفة المودود لابن القيم،
ص ٢٠، وعزاه لابن المنذر في الأوسط.
(٣) قاله النووي في الأذكار، ص٣٤٩، وانظر: صحيح الأذكار للنووي، لسليم الهلالي، ٢/ ٧١٣، وتمام التخريج في الذكر والدعاء والعلاج بالرقى للمؤلف، ١/ ٤١٦.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 41 ٤٨ - ما يعوذ به الأولاد',
  '
٤٨ - مَا يُعوَّذُ بِهِ الأَوْلاَدُ
١٤٦ - كَانَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يُعَوِّذُ الحَسَنَ وَالحُسَينَ - رضي الله عنهما - ((أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لاَمَّةٍ)) (١).
٤٩ - الدُّعَاءُ لِلْمَرِيضِ فِي عِيَادَتِهِ
١٤٧ - (١) ((لاَ بأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ)) (٢).
١٤٨ - (٢) ((أَسْأَلُ اللَّهَ الْعَظيمَ رَبَّ الْعَرْشِ الْعَظِيمِ أَنْ يَشْفيَكَ)) (سبع مرات) (٣).

--- الحواشي ---
(١) البخاري، ٤/ ١١٩، برقم ٣٣٧١، من حديث ابن عباس رَضِيَ اللَّهُ عَنْهُمَا.
(٢) البخاري مع الفتح، ١٠/ ١١٨، برقم ٣٦١٦.
(٣) ((ما من عبد مسلم يعود مريضاً لم يحضر أجله فيقول سبع مرات ... )) الحديث .. إلاَّ عوفي. أخرجه الترمذي، برقم ٢٠٨٣، وأبو داود، برقم ٣١٠٦، وانظر: صحيح الترمذي، ٢/ ٢١٠، وصحيح الجامع، ٥/ ١٨٠.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 42 ٥٠ - فضل عيادة المريض',
  '
٥٠ - فَضْلُ عِيَادَةِ المَرِيضِ
١٤٩ - قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((إِذَا عَادَ الرَّجُلُ أَخَاهُ الْمُسْلِمَ مَشَى فِي خِرَافَةِ الْجَنَّةِ حَتَّى يَجْلِسَ، فَإِذَا جَلَسَ غَمَرَتْهُ الرَّحْمَةُ، فَإِنْ كَانَ غُدْوَةً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُمْسِيَ، وَإِنْ كَانَ مَسَاءً صَلَّى عَلَيْهِ سَبْعُونَ أَلْفَ مَلَكٍ حَتَّى يُصْبِحَ)) (١).

--- الحواشي ---
(١) رواه الترمذي، برقم ٩٦٩، وابن ماجه، برقم ١٤٤٢، وأحمد، برقم ٩٧٥، وانظر: صحيح ابن ماجه، ١/ ٢٤٤ وصحيح الترمذي، ١/ ٢٨٦، وصححه أيضاً أحمد شاكر.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 43 ٥١ - دعاء المريض الذي يئس من حياته',
  '
٥١ - دُعَاءُ المَرِيضِ الَّذِي يَئِسَ مِنْ حَيَاتِهِ
١٥٠ - (١) ((اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ الْأَعْلَى)) (١).
١٥١ - (٢) ((جَعَلَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - عِنْدَ مَوْتِهِ يُدْخِلُ يَدَيْهِ فِي الْمَاءِ فَيَمْسَحُ بِهِمَا وَجْهَهُ، وَيَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ إِنَّ لِلْمَوْتِ سَكَرَاتٍ)) (٢).
١٥٢ - (٣) ((لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ المُلْكُ

--- الحواشي ---
(١) البخاري، ٧/ ١٠، برقم ٤٤٣٥، ومسلم، ٤/ ١٨٩٣، برقم ٢٤٤٤.
(٢) البخاري مع الفتح، ٨/ ١٤٤، برقم ٤٤٤٩، وفي الحديث ذكر السواك.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 44 ٥٢ - تلقين المحتضر',
  '
وَلَهُ الْحَمْدُ، لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)) (١).
٥٢ - تَلْقِينُ المُحْتَضَرِ
١٥٣ - ((مَنْ كَانَ آخِرُ كَلاَمِهِ لاَ إِلَهَ إِلاَّ اللَّهُ دَخَلَ الْجَنَّةَ)) (٢).
٥٣ - دُعَاءُ مَن أُصِيبَ بِمُصِيبَةٍ
١٥٤ - ((إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرَاً

--- الحواشي ---
(١) أخرجه الترمذي، برقم ٣٤٣٠، وابن ماجه، برقم ٣٧٩٤، وصححه الألباني، انظر: صحيح الترمذي، ٣/ ١٥٢، وصحيح ابن ماجه، ٢/ ٣١٧.
(٢) أبو داود، ٣/ ١٩٠، برقم ٣١١٦، وانظر: صحيح الجامع، ٥/ ٤٣٢.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
