INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 46 ٥٥ - الدعاء للميت في الصلاة عليه',
  '
مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، وَزَوْجَاً خَيْراً مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ القَبْرِ [وَعَذَابِ النَّارِ])) (١).
١٥٧ - (٢) ((اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَشَاهِدِنَا وَغَائِبِنَا، وَصَغِيرِنَا وَكَبيرِنَا، وَذَكَرِنَا وَأُنْثَانَا. اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الْإِسْلاَمِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا

--- الحواشي ---
(١) مسلم، ٢/ ٦٦٣، برقم ٩٦٣.

فَتَوَفَّهُ عَلَى الإِيمَانِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ)) (١).
١٥٨ - (٣) ((اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وَحَبْلِ جِوَارِكَ، فَقِهِ مِنْ فِتْنَةِ الْقَبْرِ، وَعَذَابِ النَّارِ، وَأَنْتَ أَهْلُ الْوَفَاءِ وَالْحَقِّ، فَاغْفِرْ لَهُ وَارْحَمْهُ إِنَّكَ أَنْتَ الغَفُورُ الرَّحيمُ)) (٢).
١٥٩ - (٤) ((اللَّهُمَّ عَبْدُكَ وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ

--- الحواشي ---
(١) أبو داود، برقم ٣٢٠١، والترمذي، برقم ١٠٢٤، والنسائي، برقم ١٩٨٥، وابن ماجه، ١/ ٤٨٠، برقم ١٤٩٨، وأحمد، ٢/ ٣٦٨، برقم ٨٨٠٩، وانظر: صحيح ابن ماجه، ١/ ٢٥١.
(٢) أخرجه ابن ماجه، برقم ١٤٩٩، انظر: صحيح ابن ماجه، ١/ ٢٥١، ورواه أبو داود، ٣/ ٢١١، برقم ٣٢٠٢.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 47 ٥٦ - الدعاء للفرط في الصلاة عليه',
  '
عَذَابِهِ، إِنْ كَانَ مُحْسِناً فَزِدْ فِي حَسَنَاتِهِ، وَإِنْ كَانَ مُسِيئاً فَتَجَاوَزْ عَنْهُ)) (١).
٥٦ - الدُّعَاءُ لِلْفَرَطِ فِي الصَّلاَةِ عَلَيْهِ
١٦٠ - (١) ((اللَّهُمَّ أَعِذْهُ مِنْ عَذَابِ القَبْرِ)) (٢).
وإن قال: ((اللَّهُمَّ اجْعَلْهُ فَرَطاً وَذُخْراً لِوَالِدَيْهِ، وَشَفِيعاً مُجَاباً، اللَّهُمَّ ثَقِّلْ بِهِ مَوَازِينَهُمَا، وَأَعْظِمْ بِهِ أُجورَهُمَا،

--- الحواشي ---
(١) أخرجه الحاكم وصححه ووافقه الذهبي، ١/ ٣٥٩، وانظر: أحكام الجنائز للألباني، ص١٢٥.
(٢) ((قال سعيد بن المسيب: صلّيتُ وراء أبي هريرة على صبيٍّ لم يعمل خطيئة قَطُّ، فسمعته يقول .. )) الحديث. أخرجه مالك في الموطأ، ١/ ٢٨٨، وابن أبي شيبة في المصنف، ٣/ ٢١٧، والبيهقي، ٤/ ٩، وصحح إسناده شعيب الأرناؤوط في تحقيقه لشرح السنة للبغوي، ٥/ ٣٥٧.

وَأَلْحِقْهُ بِصَالِحِ الْمُؤْمِنِينَ، وَاجْعَلْهُ فِي كَفَالَةِ إِبْرَاهِيمَ، وَقِهِ بِرَحْمَتِكَ عَذَابَ الْجَحِيمِ، وَأَبْدِلْهُ دَاراً خَيْراً مِنْ دَارِهِ، وَأَهْلاً خَيْراً مِنْ أَهْلِهِ، اللَّهُمَّ اغْفِرْ لِأَسْلاَفِنَا، وَأَفْرَاطِنَا، وَمَنْ سَبَقَنَا بِالْإِيمَانِ)) فَحَسَنٌ (١).
١٦١ - (٢) ((اللَّهُمَّ اجْعَلْهُ لَنَا فَرَطاً، وَسَلَفاً، وَأَجْراً)) (٢).

--- الحواشي ---
(١) انظر: المغني لابن قدامة، ٣/ ٤١٦، والدروس المهمة لعامة الأمة، للشيخ عبد العزيز بن عبد الله بن باز - رحمه الله -، ص١٥.
(٢) كان الحسن يقرأ على الطفل بفاتحة الكتاب، ويقول ... الحديث. أخرجه البغوي في شرح السنة، ٥/ ٣٥٧، وعبد الرزاق، برقم ٦٥٨٨، وعلقه البخاري في كتاب الجنائز، ٦٥ باب قراءة فاتحة الكتاب على الجنازة، ٢/ ١١٣، قبل الحديث رقم ١٣٣٥.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 48 ٥٧ - دعاء التعزية',
  '
٥٧ - دُعَاءُ التَّعْزِيَةِ
١٦٢ - ((إِنَّ للَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمَّى ... فَلْتَصْبِرْ وَلْتَحْتَسِبْ)) (١).
وَإِنْ قَالَ: ((أَعْظَمَ اللَّهُ أَجْرَكَ، وَأَحْسَنَ عَزَاءَكَ، وَغَفَرَ لِمَيِّتِكَ)) فَحَسَنٌ (٢).
٥٨ - الدُّعَاءُ عِنْدَ إِدْخَالِ الميِّتِ الْقَبْرَ
١٦٣ - ((بِسْمِ اللَّهِ وَعَلَى سُنَّةِ رَسُولِ اللَّهِ)) (٣).

--- الحواشي ---
(١) البخاري، ٢/ ٨٠، برقم ١٢٨٤، ومسلم، ٢/ ٦٣٦، برقم ٩٢٣.
(٢) الأذكار للنووي، ص١٢٦.
(٣) أبو داود، ٣/ ٣١٤، برقم ٣٢١٥، بسند صحيح، وأحمد، برقم ٥٢٣٤، ورقم ٤٨١٢ بلفظ: ((بسم اللَّه، وعلى ملّة رسول اللَّه))، وسنده صحيح.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 49 ٥٩ - الدعاء بعد دفن الميت',
  '
٥٩ - الدُّعَاءُ بَعْدَ دَفْنِ المَيِّتِ
١٦٤ - ((اللَّهُمَّ اغْفِرْ لَهُ، اللَّهُمَّ ثَبِّتْهُ)) (١).
٦٠ - دُعَاءُ زِيَارَةِ الْقُبُورِ
١٦٥ - ((السَّلاَمُ عَلَيْكُمْ أَهْلَ الدِّيَارِ، مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لاَحِقُونَ، [وَيَرْحَمُ اللَّهُ الْمُسْتَقدِمِينَ مِنَّا وَالْمُسْتأْخِرِينَ] أَسْاَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ)) (٢).

--- الحواشي ---
(١) كان النبي - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إذا فرغ من دفن الميت وقف عليه وقال: ((استغفروا لأخيكم، وسلوا له التثبيت؛ فإنه الآن يُسأل)). أبو داود، ٣/ ٣١٥، برقم ٣٢٢٣، والحاكم وصححه، ووافقه الذهبي ١/ ٣٧٠.
(٢) مسلم، ٢/ ٦٧١، برقم ٩٧٥، وابن ماجه، ١/ ٤٩٤، واللفظ له، برقم ١٥٤٧ عن بريدة - رضي الله عنه -، وما بين المعقوفين من حديث عائشة - رضي الله عنها - عند مسلم، ٢/ ٦٧١، برقم ٩٧٥.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 50 ٦١ - دعاء الريح',
  '
٦١ - دُعَاءُ الرِّيحِ
١٦٦ - (١) ((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَأَعُوذُ بِكَ مِنْ شَرِّهَا)) (١).
١٦٧ - (٢) ((اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا فِيهَا، وَخَيْرَ مَا أُرْسِلَتْ بِهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا، وَشَرِّ مَا فِيهَا، وَشَرِّ مَا أُرْسِلَتْ بِهِ)) (٢).

--- الحواشي ---
(١) أخرجه أبو داود، ٤/ ٣٢٦، برقم ٥٠٩٩، وابن ماجه، ٢/ ١٢٢٨، برقم ٣٧٢٧، وانظر: صحيح ابن ماجه، ٢/ ٣٠٥.
(٢) مسلم، واللفظ له، ٢/ ٦٦٦، برقم ٨٩٩، والبخاري، ٤/ ٧٦ برقم ٣٢٠٦، ورقم ٤٨٢٩.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 51 ٦٢ - دعاء الرعد',
  '
٦٢ - دُعَاءُ الرَّعْدِ
١٦٨ - ((سُبْحَانَ الَّذِي يُسَبِّحُ الرَّعْدُ بِحَمْدِهِ وَالْمَلاَئِكةُ مِنْ خِيفَتِهِ)) (١).
