١٧٠ - (٢) ((اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا،

--- الحواشي ---
(١) كان عبد الله بن الزبير - رضي الله عنهما - إذا سمع الرعد ترك الحديث وقال: ... الحديث، الموطأ، ٢/ ٩٩٢، وقال الألباني في صحيح الكلم الطيب، ١٥٧: ((صحيح الإسناد موقوفاً)).
(٢) أبو داود، ١/ ٣٠٣، برقم ١١٧١، وصححه الألباني في صحيح أبي داود، ١/ ٢١٦.
