INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 62 ٨٤ - ما يقال في المجلس',
  '
٨٤ - مَا يُقَالُ فِي المَجْلِسِ
١٩٥ - ((عَنِ ابْنِ عُمَرَ - رضي الله عنهما - قَاَلَ: كَانَ يُعَدُّ لِرَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فِي الْمَجْلِسِ الوَاحِدِ مِائَةُ مَرَّةٍ مِنْ قَبْلِ أَنْ يَقُومَ: ((رَبِّ اغْفِرْ لِي، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الغَفُورُ)) (١).
٨٥ - كَفَّارَةُ المَجْلِسِ
١٩٦ - ((سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ أَنْتَ، أَسْتَغْفِرُكَ وَأَتُوبُ إِلَيْكَ)) (٢).

--- الحواشي ---
(١) الترمذي، برقم ٣٤٣٤، وابن ماجه، برقم ٣٨١٤، وانظر: صحيح الترمذي، ٣/ ١٥٣، وصحيح ابن ماجه، ٢/ ٣٢١، ولفظه للترمذي.
(٢) أصحاب السنن: أبو داود، برقم ٤٨٥٨، والترمذي، برقم ٣٤٣٣، والنسائي، برقم ١٣٤٤، وانظر صحيح الترمذي ٣/ ١٥٣، وقد ثبت أن عائشة - رضي الله عنها - قالت: ((ما جلس رسول اللَّه - صلى الله عليه وسلم - مجلساً، ولا تَلا قرآناً، ولا صلَّى صلاةً إلا ختم ذلك بكلمات ... )) الحديث، أخرجه النسائي في عمل اليوم والليلة، برقم ٣٠٨، وأحمد، ٦/ ٧٧، برقم ٢٤٤٨٦، وصححه الدكتور فاروق حمادة في تحقيقه لعمل اليوم والليلة للنسائي، ص٢٧٣.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
