  '
١٠٣ - دُعاءُ المُسَافِرِ إِذَا أَسْحَرَ
٢١٥ - ((سَمَّعَ سَامِعٌ بِحَمْدِ اللَّهِ، وَحُسْنِ بَلاَئِهِ عَلَيْنَا، رَبَّنَا صاحِبْنَا، وَأَفْضِلْ عَلَيْنَا، عَائِذاً بِاللَّهِ مِنَ النَّارِ)) (١).
١٠٤ - الدُّعَاءُ إِذَا نَزَلَ مَنْزِلاً فِي سَفَرٍ أَوْ غَيْرِهِ
٢١٦ - ((أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ شَرِّ مَا خَلَقَ)) (٢).

--- الحواشي ---
(١) مسلم، ٤/ ٢٠٨٦، برقم ٢٧١٨، ومعنى سَمعَ سامِعٌ: أي شهد شاهدٌ على حمدنا للَّه تعالى على نعمه، وحسن بلائه. ومعنى سَمَّعَ سامِعٌ: بلَّغ سامع قولي هذا لغيره، وقال مثله تنبيهاً على الذكر في السحر والدعاء. شرح النووي على صحيح مسلم، ١٧/ ٣٩.
(٢) مسلم، ٤/ ٢٠٨٠، برقم ٢٧٠٩.
',
