INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 73 ١٠٥ - ذكر الرجوع من السفر',
  '
١٠٥ - ذِكْرُ الرُّجُوعِ مِنَ السَّفَرِ
٢١٧ - ((يُكَبِّرُ عَلَى كُلِّ شَرَفٍ ثَلاَثَ تَكْبِيرَاتٍ ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنا حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزابَ وَحْدَهُ)) (١).
١٠٦ - مَا يَقُولُ مَنْ أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يَكْرَهُهُ
٢١٨ - ((كَانَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إِذَا أَتَاهُ الْأَمْرُ

--- الحواشي ---
(١) كان النبي - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يقوله إذا قَفَلَ من غزوٍ أو حجٍّ، البخاري، ٧/ ١٦٣، برقم ١٧٩٧، ومسلم، ٢/ ٩٨٠، برقم ١٣٤٤.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 74 ١٠٧ - فضل الصلاة على النبي - صلى الله عليه وسلم -',
  '
يَسُرُّهُ قَالَ: ((الْحَمْدُ لِلَّهِ الَّذِي بِنِعْمَتِهِ تَتِمُّ الصَّالِحَاتُ)) وَإِذَا أَتَاهُ الْأَمْرُ يَكْرَهُهُ قَالَ: ((الْحَمْدُ لِلَّهِ عَلَى كُلِّ حَالٍ)) (١).
١٠٧ - فَضْلُ الصَّلاَةِ عَلَى النَّبيِّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -
٢١٩ - (١) قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((مَنْ صَلَّى عَلَيَّ صَلاَةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْراً)) (٢).
٢٢٠ - (٢) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((لاَ تَجْعَلُوا قَبْرِي عِيداً وَصَلُّوا عَلَيَّ؛ فَإِنَّ صَلاَتَكُم

--- الحواشي ---
(١) أخرجه ابن السني في عمل اليوم والليلة، برقم ٣٧٧، والحاكم وصححه، ١/ ٤٩٩، وصححه الألباني في صحيح الجامع، ٤/ ٢٠١.
(٢) أخرجه مسلم، ١/ ٢٨٨، برقم ٣٨٤.

تَبْلُغُنِي حَيْثُ كُنْتُمْ)) (١).
٢٢١ - (٣) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((الْبَخِيلُ مَنْ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ)) (٢).
٢٢٢ - (٤) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((إِنَّ لِلَّهِ مَلاَئِكَةً سَيَّاحِينَ فِي الْأَرْضِ يُبَلِّغُونِي مِنْ أُمَّتِي السَّلاَمَ)) (٣).
٢٢٣ - (٥) ((وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((مَا مِنْ أَحَدٍ يُسَلِّمُ عَلَيَّ إِلاَّ رَدَّ اللَّهُ عَلَيَّ رُوحِيَ حَتَّى

--- الحواشي ---
(١) أبو داود، ٢/ ٢١٨، برقم ٢٠٤٤، وأحمد، ٢/ ٣٦٧، برقم ٨٨٠٤، وصححه الألباني في صحيح أبي داود، ٢/ ٣٨٣.
(٢) الترمذي، ٥/ ٥٥١، برقم ٣٥٤٦، وغيره، وانظر: صحيح الجامع، ٣/ ٢٥، وصحيح الترمذي، ٣/ ١٧٧.
(٣) النسائي، ٣/ ٤٣، برقم ١٢٨٢، والحاكم، ٢/ ٤٢١، وصححه الألباني في صحيح النسائي، ١/ ٢٧٤.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 75 ١٠٨ - إفشاء السلام',
  '
أَرُدَّ عَلَيْهِ السَّلاَمَ)) (١).
١٠٨ - إِفْشَاءُ السَّلاَمِ
٢٢٤ - (١) قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((لاَ تَدْخُلُوا الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلاَ تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلاَ أَدُلُّكُم عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُم، أَفْشُوا السَّلاَمَ بَيْنَكُمْ)) (٢).
٢٢٥ - (٢) ((ثَلاَثٌ مَنْ جَمَعَهُنَّ فَقَدْ جَمَعَ الْإِيمَانَ: الْإِنْصَافُ مِنْ نَفْسِكَ، وَبَذْلُ السَّلاَمِ لِلْعَالَمِ، وَالْإِنْفَاقُ مِنَ الإِقْتَارِ)) (٣).

--- الحواشي ---
