INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 78 ١١٣ - ما يقول المسلم إذا مدح المسلم',
  '
مُؤْمِنٍ سَبَبْتُهُ فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ)) (١).
١١٣ - مَا يَقُولُ المُسْلِمُ إِذَا مَدَحَ المُسْلِمَ
٢٣١ - قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((إِذَا كَانَ أَحَدُكُم مَادِحاً صَاحِبَهُ لاَ مَحَالَةَ فَلْيَقُلْ: أَحْسِبُ فُلاَناً وَاللَّهُ حَسِيبُهُ، وَلاَ أُزَكِّي عَلَى اللَّهِ أَحَداً، أَحْسِبُهُ - إِنْ كَانَ يَعْلَمُ ذَاكَ - كَذَا وَكَذَا)) (٢).
١١٤ - مَا يَقُولُ المُسْلِمُ إِذَا زُكِّيَ
٢٣٢ - ((اللَّهُمَّ لاَ تُؤَاخِذْنِي بِمَا يَقُولُونَ،

