٢٣٣ - ((لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ، وَالنِّعْمَةَ، لَكَ وَالْمُلْكَ، لاَ شَرِيكَ لَكَ)) (٢).
١١٦ - التَّكْبِيرُ إِذَا أَتَى الْحَجَرَ الأَسْوَدَ
٢٣٤ - ((طَافَ النَّبيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - بِالْبَيْتِ عَلَى

