(٢) أبو داود، ٢/ ١٧٩، برقم ١٨٩٤، وأحمد، ٣/ ٤١١، برقم ١٥٣٩٨، والبغوي في شرح السنة، ٧/ ١٢٨، وحسنه الألباني في صحيح أبي داود، ١/ ٣٥٤، والآية من سورة البقرة: ٢٠١.
