INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 82 ١١٩ - الدعاء يوم عرفة',
  '
١١٩ - الدُّعَاءُ يَوْمَ عَرَفَةَ
٢٣٧ - قَالَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((خَيْرُ الدُّعَاءِ دُعَاءُ يَوْمِ عَرَفَةَ، وَخَيْرُ مَا قُلْتُ أَنَا وَالنَّبيُّونَ مِنْ قَبْلِي: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ)) (١).
١٢٠ - الذِّكْرُ عِنْدَ المَشْعَرِ الْحَرَامِ
٢٣٨ - ((رَكِبَ النَّبِيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - الْقَصْوَاءَ حَتَّى أَتَى الْمَشْعَرَ الْحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ (فَدَعَاهُ، وَكَبَّرَهُ، وَهَللَّهُ، وَوَحَّدَهُ) فَلَمْ

--- الحواشي ---
(١) الترمذي، برقم ٣٥٨٥، وحسنه الألباني في صحيح الترمذي، ٣/ ١٨٤، وفي سلسلة الأحاديث الصحيحة، ٤/ ٦.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 83 ١٢١ - التكبير عند رمي الجمار مع كل حصاة',
  '
يَزَلْ وَاقِفاً حَتَّى أَسْفَرَ جِدَّاً فَدَفَعَ قَبْلَ أَنْ تَطْلُعَ الشَّمسُ)) (١).
١٢١ - التَّكْبِيرُ عِنْدَ رَمْي ِ الْجِمَارِ مَعَ كُلِّ حَصَاةٍ
٢٣٩ - ((يُكَبِّرُ كُلَّمَا رَمَى بِحَصَاةٍ عِنْدَ الْجِمَارِ الثَّلاَثِ، ثُمَّ يَتَقَدَّمُ، ويَقِفُ يَدْعُو مُسْتَقْبِلَ الْقِبلَةِ، رَافِعاً يَدَيْهِ بَعْدَ الْجَمْرَةِ الْأُولَى وَالثَّانِيَةِ. أَمَّا جَمْرَةُ الْعَقَبَةِ فَيَرْمِيهَا وَيُكَبِّرُ عِنْدَ كُلِّ حَصَاةٍ وَيَنْصَرِفُ وَلاَ يَقِفُ عِنْدَهَا)) (٢).

--- الحواشي ---
(١) مسلم، ٢/ ٨٩١، برقم ١٢١٨.
(٢) البخاري مع الفتح، ٣/ ٥٨٣، برقم ١٧٥١، وانظر لفظه هناك. والبخاري مع الفتح، ٣/ ٥٨٣، و٣/ ٥٨٤، و٣/ ٥٨١، برقم ١٧٥٣، ورواه مسلم أيضاً، برقم ١٢١٨.
',
  9,
  1,
  1,
  'published',
  1,
  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 84 ١٢٢ - دعاء التعجب والأمر السار',
  '
١٢٢ - دُعَاءُ التَّعَجُّبِ وَالأَمْرِ السَّارِّ
٢٤٠ - (١) ((سُبْحَانَ اللَّهِ!)) (١).
٢٤١ - (٢) ((اللَّهُ أَكْبَرُ!)) (٢).
١٢٣ - مَا يَفْعَلُ مَنْ أَتَاهُ أَمْرٌ يَسُرُّهُ
٢٤٢ - ((كَانَ النَّبيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - إِذَا أَتَاهُ أَمْرٌ يَسُرُّهُ أَوْ يُسَرُّ بِهِ خَرَّ سَاجِداً شُكْراً لِلَّهِ تَبَارَكَ وَتَعَالَى)) (٣).

--- الحواشي ---
(١) البخاري مع الفتح، ١/ ٢١٠، و٣٩٠، و٤١٤، برقم، ١١٥، ورقم ٣٥٩٩، ورقم ٦٢١٨، ومسلم، ٤/ ١٨٥٧، برقم ١٦٧٤.
(٢) البخاري مع الفتح، ٨/ ٤٤١، برقم ٤٧٤١، وبرقم ٣٠٦٢، والترمذي، برقم ٢١٨٠، والنسائي في الكبرى، برقم ١١١٨٥، وانظر: صحيح الترمذي، ٢/ ١٠٣، و٢/ ٢٣٥، ومسند أحمد،
٥/ ٢١٨، برقم ٢١٩٠٠.
(٣) رواه أهل السنن إلا النسائي: أبو داود، برقم ٢٧٧٤، والترمذي، برقم ١٥٧٨، وابن ماجه، برقم ١٣٩٤. انظر صحيح ابن ماجه، ١/ ٢٣٣، وإرواء الغليل، ٢/ ٢٢٦.
',
