  '
١٢٦ - مَا يُقَالُ عِنْدَ الْفَزَعِ
٢٤٥ - ((لاَ إِلَهَ إِلاَّ اللَّهُ!)) (١).
١٢٧ - مَا يَقُولُ عِنْدَ الذَّبْحِ أَوِ النَّحْرِ
٢٤٦ - ((بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ [اللَّهُمَّ مِنْكَ وَلَكَ] اللَّهُمَّ تَقَبَّلْ مِنِّي)) (٢).
