(٢) مسلم، ٣/ ١٥٥٧، برقم ١٩٦٧، والبيهقي، ٩/ ٢٨٧ وما بين المعقوفين للبيهقي، ٩/ ٢٨٧ وغيره، والجملة الأخيرة سقتها بالمعنى من رواية مسلم.
