INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 87 ١٢٩ - الاستغفار والتوبة',
  '
لاَ يُجَاوِزُهُنَّ بَرٌّ وَلاَ فَاجِرٌ: مِنْ شَرِّ مَا خَلَقَ، وَبَرَأَ وَذَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ، وَمِنْ شَرِّ مَا يَعْرُجُ فيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ، وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلاَّ طَارِقاً يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ)) (١).
١٢٩ - الاستِغْفَارُ والتَّوبَةُ
٢٤٨ - (١) قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((وَاللَّهِ

--- الحواشي ---
(١) أحمد، ٣/ ٤١٩، برقم ١٥٤٦١، بإسناد صحيح، وابن السني، برقم ٦٣٧، وصحح إسناده الأرناؤوط في تخريجه للطحاوية، ص١٣٣، وانظر: مجمع الزوائد، ١٠/ ١٢٧.

إِنِّي لأَسْتَغفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ فِي الْيَوْمِ أَكْثَرَ مِنْ سَبْعِينَ مَرَّةٍ)) (١).
٢٤٩ - (٢) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((يَا أَيُّهَا النَّاسُ تُوبُوا إِلَى اللَّهِ فَإِنِّي أَتُوبُ فِي الْيَوْمِ إِلَيْهِ مِائَةَ مَرَّةٍ)) (٢).
٢٥٠ - (٣) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((مَنْ قَالَ أَسْتَغْفِرُ اللَّهَ الْعَظيمَ الَّذِي لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ القَيّوُمُ وَأَتُوبُ إِلَيهِ، غَفَرَ اللَّهُ لَهُ وَإِنْ كَانَ فَرَّ مِنَ الزَّحْفِ)) (٣).

--- الحواشي ---
(١) البخاري مع الفتح، ١١/ ١٠١، برقم ٦٣٠٧.
(٢) مسلم، ٤/ ٢٠٧٦، برقم ٢٧٠٢.
(٣) أبو داود، ٢/ ٨٥، برقم ١٥١٧، والترمذي، ٥/ ٥٦٩، برقم ٣٥٧٧، والحاكم وصححه ووافقه الذهبي، ١/ ٥١١، وصححه الألباني، انظر: صحيح الترمذي، ٣/ ١٨٢، وجامع الأصول لأحاديث الرسول - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -، ٤/ ٣٨٩ - ٣٩٠ بتحقيق الأرناؤوط.

٢٥١ - (٤) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((أَقْرَبُ مَا يَكُونُ الرَّبُّ مِنَ الْعَبْدِ فِي جَوْفِ اللَّيْلِ الآخِرِ فَإِنِ اسْتَطَعْتَ أَنْ تَكُونَ مِمَّنْ يَذْكُرُ اللَّهَ فِي تِلْكَ السَّاعَةِ فَكُنْ)) (١).
٢٥٢ - (٥) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ فَأَكثِرُوا الدُّعَاءَ)) (٢).

--- الحواشي ---
(١) الترمذي، برقم ٣٥٧٩، والنسائي، ١/ ٢٧٩، برقم ٥٧٢، والحاكم،
١/ ٣٠٩، وانظر: صحيح الترمذي، ٣/ ١٨٣، وجامع الأصول بتحقيق الأرناؤوط، ٤/ ١٤٤.
(٢) مسلم، ١/ ٣٥٠، برقم ٤٨٢.
',
