  'سعيد بن وهف القحطاني'
);
INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 88 ١٣٠ - فضل التسبيح والتحميد، والتهليل، والتكبير',
  '
٢٥٣ - (٦) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((إِنَّهُ لَيُغَانُ عَلَى قَلْبِي وَإِنِّي لأَسْتَغْفِرُ اللَّهَ فِي الْيَوْمِ مِائَةَ مَرَّةٍ)) (١).
١٣٠ - فَضْلُ التَّسْبِيحِ وَالتَّحْمِيدِ، وَالتَّهْلِيلِ، وَالتَّكْبِيرِ
٢٥٤ - (١) ((قَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - مَنْ قَالَ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ فِي يَوْمٍ مِائَةَ مَرَّةٍ حُطَّتْ خَطَايَاهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْر)) (٢).

--- الحواشي ---
(١) أخرجه مسلم، ٤/ ٢٠٧٥، برقم ٢٧٠٢، قال ابن الأثير: ((ليُغان على قلبي))، أي ليُغطَّى ويُغشى، والمراد به: السهو؛ لأنه كان - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - لا يزال في مزيد من الذكر والقربة ودوام المراقبة، فإذا سها عن شيء منها في بعض الأوقات، أو نسي، عَدّهُ ذَنباً على نفسه، ففزع إلى الاستغفار. انظر: جامع الأصول، ٤/ ٣٨٦.
(٢) البخاري، ٧/ ١٦٨، برقم ٦٤٠٥، ومسلم، ٤/ ٢٠٧١، برقم ٢٦٩١، وانظر: فضل من قالها مائة مرة إذا أصبح وإذا أمسى، ص ٦٥ من هذا الكتاب.

٢٥٥ - (٢) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((مَنْ قَالَ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ عَشْرَ مِرَارٍ، كَانَ كَمَنْ أَعْتَقَ أَرْبَعَةَ أَنْفُسٍ مِنْ وَلَدِ إِسْمَاعِيلَ)) (١).
٢٥٦ - (٣) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((كَلِمَتَانِ خَفِيفَتَانِ عَلَى اللِّسَانِ، ثَقِيلَتَانِ فِي الْمِيزَانِ، حَبِيبَتَانِ إِلَى الرَّحْمَنِ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحانَ اللَّهِ الْعَظِيمِ)) (٢).

--- الحواشي ---
(١) البخاري، ٧/ ٦٧، برقم ٦٤٠٤، ومسلم بلفظه، ٤/ ٢٠٧١، برقم ٢٦٩٣، وانظر: فضل من قالها في اليوم مائة مرة: الدعاء رقم ٩٣، ص ٦٦ من هذا الكتاب.
(٢) البخاري، ٧/ ١٦٨، برقم ٦٤٠٤، ومسلم، ٤/ ٢٠٧٢، برقم ٢٦٩٤.

٢٥٧ - (٤) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((لَأَنْ أَقُولَ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، أَحَبُّ إِلَيَّ مِمَّا طَلَعَتْ عَلَيْهِ الشَّمسُ)) (١).
٢٥٨ - (٥) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((أَيَعْجِزُ أَحَدُكُم أَنْ يَكْسِبَ كُلَّ يَوْمٍ أَلْفَ حَسَنَةٍ)) فَسَأَلَهُ سَائِلٌ مِنْ جُلَسَائِهِ كَيْفَ يَكْسِبُ أَحَدُنَا أَلْفَ حَسَنَةٍ؟ قَالَ: ((يُسَبِّحُ مِائَةَ تَسْبِيحَةٍ، فَيُكتَبُ لَهُ أَلْفُ حَسَنَةٍ أَوْ يُحَطُّ عَنْهُ أَلْفُ خَطِيئَةٍ)) (٢).

--- الحواشي ---
(١) مسلم، ٤/ ٢٠٧٢، برقم ٢٦٩٥.
(٢) مسلم، ٤/ ٢٠٧٣، برقم ٢٦٩٨.

٢٥٩ - (٦) ((مَنْ قَالَ: سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ غُرِسَتْ لَهُ نَخْلَةٌ فِي الْجَنَّةِ)) (١).
٢٦٠ - (٧) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((يَا عَبْدَ اللَّهِ بْنَ قَيْسٍ أَلاَ أَدُلُّكَ عَلَى كَنْزٍ مِنْ كُنُوزِ الْجَنَّةِ))؟ فَقُلْتُ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: ((قُلْ لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)) (٢).
٢٦١ - (٨) وَقَالَ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((أَحَبُّ الْكَلاَمِ إِلَى اللَّهِ أَرْبَعٌ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ

--- الحواشي ---
(١) أخرجه، الترمذي، ٥/ ٥١١، برقم ٣٤٦٤، والحاكم، ١/ ٥٠١، وصححه ووافقه الذهبي، وانظر: صحيح الجامع، ٥/ ٥٣١، وصحيح الترمذي، ٣/ ١٦٠.
(٢) البخاري مع الفتح، ١١/ ٢١٣، برقم ٤٢٠٦، ومسلم، ٤/ ٢٠٧٦، برقم ٢٧٠٤.

إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، لاَ يَضُرُّكَ بِأَيِّهِنَّ بَدَأتَ)) (١).
٢٦٢ - (٩) جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - فَقَالَ: عَلِّمْنِي كَلاماً أَقُولُهُ: قَالَ: ((قُلْ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، اللَّهُ أَكْبَرُ كَبِيراً، وَالْحَمْدُ لِلَّهِ كَثِيراً، سُبْحَانَ اللَّهِ رَبِّ العَالَمِينَ، لاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ الْعَزِيزِ الْحَكِيمِ)) قَالَ: فَهَؤُلاَءِ لِرَبِّي، فَمَا لِي؟ قَالَ: ((قُلْ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَاهْدِنِي،

--- الحواشي ---
(١) مسلم، ٣/ ١٦٨٥، برقم ٢١٣٧.

وَارْزُقْنِي)) (١).
٢٦٣ - (١٠) كَانَ الرَّجُلُ إِذَا أَسْلَمَ عَلَّمَهُ النَّبيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - الصَّلاَةَ ثُمَّ أَمَرَهُ أَنْ يَدْعُوَ بِهَؤُلاَءِ الْكَلِمَاتِ: ((اللَّهُمَّ اغْفِرِ لِي، وَارْحَمْنِي، وَاهْدِنِي، وَعَافِنِي وَارْزُقْنِي)) (٢).
٢٦٤ - (١١) ((إِنَّ أَفْضَلَ الدُّعَاءِ الْحَمْدُ لِلَّهِ، وَأَفْضَلَ الذِّكْرِ لاَ إِلَهَ إِلاَّ اللَّهُ)) (٣).

--- الحواشي ---
(١) مسلم، ٤/ ٢٠٧٢، برقم ٢٦٩٦، وزاد أبو داود، ١/ ٢٢٠، برقم ٨٣٢: فلما ولّى الأعرابي قال النبي - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ -: ((لقد ملأ يده من الخير)).
(٢) مسلم، ٤/ ٢٠٧٣، برقم ٣٦٩٧، وفي رواية له أيضاً: ((فإن هؤلاء تجمع لك دنياك وآخرتك)).
(٣) الترمذي، ٥/ ٤٦٢، برقم ٣٣٨٣، وابن ماجه، ٢/ ١٢٤٩، برقم ٣٨٠٠، والحاكم، ١/ ٥٠٣،وصححه ووافقه الذهبي، وانظر: صحيح الجامع، ١/ ٣٦٢.
',
