INSERT INTO songs (title, content_raw, category_id, author_id, approval_score, status, last_editor_id, author) VALUES (
  'حصن المسلم من أذكار الكتاب والسنة - 89 ١٣١ - كيف كان النبي - صلى الله عليه وسلم - يسبح؟',
  '
٢٦٥ - (١٢) ((الْبَاقِيَاتُ الصَّالِحَاتُ: سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ)) (١).
١٣١ - كَيْفَ كَانَ النَّبيُّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يُسَبِّحُ؟
٢٦٦ - عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو - رضي الله عنهما - قَالَ: ((رَأَيْتُ النَّبيَّ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - يَعْقِدُ التَّسْبِيحَ)) وفي زيادةٍ: ((بِيَمِينِهِ)) (٢).

--- الحواشي ---
(١) أحمد، برقم ٥١٣، بترتيب أحمد شاكر، وانظر: مجمع الزوائد، ١/ ٢٩٧، وعزاه ابن حجر في بلوغ المرام من رواية أبي سعيد إلى النسائي [في الكبرى]، برقم ١٠٦١٧، وقال: صححه ابن حبان، [برقم ٨٤٠]، والحاكم [١/ ٥٤١].
(٢) أخرجه أبو داود بلفظه، ٢/ ٨١، برقم ١٥٠٢، والترمذي، ٥/ ٥٢١، برقم ٣٤٨٦، وانظر: صحيح الجامع، ٤/ ٢٧١، برقم ٤٨٦٥، وصححه الألباني في صحيح سنن أبي داود، ١/ ٤١١.
',
